using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
namespace IrisDesktop {
 public static class ProgressQuantityFixture {
  static void Need(bool ok,string why){if(!ok)throw new Exception(why);}
  static void Bind(object c,Func<object,Task<bool>> approve){var m=c.GetType().GetMethod("BindQuantityApproval",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);Need(m!=null,"native quantity approval contract missing");m.Invoke(c,new object[]{approve});}
  sealed class Disk:IProgressFileIO {readonly ProgressFileIO real=new ProgressFileIO();internal bool fail;internal Action afterRead;public byte[] ReadCipher(string p,int n){var bytes=real.ReadCipher(p,n);var callback=afterRead;afterRead=null;if(callback!=null)callback();return bytes;}public void WriteNewAndFlush(string p,byte[] b){if(fail)throw new IOException("synthetic-full");real.WriteNewAndFlush(p,b);}public void ReplaceWithBackup(string t,string p,string b){real.ReplaceWithBackup(t,p,b);}public void MoveNew(string t,string p){real.MoveNew(t,p);}public IDisposable AcquireExclusiveLock(string p){return real.AcquireExclusiveLock(p);}}
  sealed class Rig {
   internal ProgressHostFixture.Trial t;internal object c;internal long ticks=1000;internal Disk disk=new Disk();
   internal async Task Start(string root,bool lost=false,bool timer=false){t=new ProgressHostFixture.Trial(root);t.store=new DesktopErgonProgressStore(t.root,"development",disk);t.lost=lost;
    if(timer){var constructor=typeof(DesktopLifeExecutor).Assembly.GetType("IrisDesktop.DesktopLifeProgressConnection").GetConstructors(System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SingleOrDefault(x=>x.GetParameters().Length==5);Need(constructor!=null,"monotonic timer injection missing");c=constructor.Invoke(new object[]{t.actor,t.journal,t.store,new Func<long>(()=>DesktopLifePolicy.Time(t.now)),new Func<long>(()=>ticks)});}else c=ProgressHostFixture.Attach(t);
    var p=await ProgressHostFixture.Bound(t,c);await t.Confirm(p);await ProgressHostFixture.Wait(t);
   }
   internal ProgressSnapshot Snapshot(){return t.store.Load(ProgressHostFixture.Scope());}
   internal Dictionary<string,object> Payload(long q,bool correct=false){var p=ProgressHostFixture.ConfirmPayload(Snapshot(),q);if(correct){p["supersedesEventId"]=Snapshot().view.goals.Single().requests.Single().confirmations.Last().eventId;p["reason"]="synthetic correction";}return p;}
   internal Task<object> Send(Dictionary<string,object> p,bool correct=false){return ProgressHostFixture.Request(c,correct?"correctQuantity":"confirmQuantity",p);}
   internal void Quantity(long q){var g=Snapshot().view.goals.Single();Need(g.confirmedQuantity==q&&g.requests.Single().quantity==q,"quantity mismatch");Need(g.requests.Single().confirmations.Last().source=="user-confirmed","official source fabricated");}
  }
  static async Task Blocked(Rig r,Dictionary<string,object> p,bool correct=false){var before=File.ReadAllBytes(r.t.store.FilePath);bool rejected=false;try{await r.Send(p,correct);}catch{rejected=true;}Need(rejected&&before.SequenceEqual(File.ReadAllBytes(r.t.store.FilePath)),"rejected quantity changed current");Need(!r.t.actor.Busy,"mutation Busy leaked");using(r.t.journal.AcquireExecutionLease()){};}
  public static async Task Run(string root){int failed=0;Func<string,Func<Task>,Task> test=async(id,body)=>{try{await body();Console.WriteLine("PASS "+id);}catch(Exception e){failed++;Console.WriteLine("FAIL "+id+": "+e.Message);}};
   await test("V01 zero requires native approval",async()=>{var r=new Rig();await r.Start(root);int prompts=0;Bind(r.c,x=>{prompts++;return Task.FromResult(true);});await r.Send(r.Payload(0));r.Quantity(0);Need(prompts==1&&r.t.calls==1,"zero approval or consumption");});
   await test("V02 extra output not clamped",async()=>{var r=new Rig();await r.Start(root);Bind(r.c,x=>Task.FromResult(true));await r.Send(r.Payload(5));r.Quantity(5);});
   await test("V03 correction replaces contribution",async()=>{var r=new Rig();await r.Start(root);await r.Send(r.Payload(3));Bind(r.c,x=>Task.FromResult(true));await r.Send(r.Payload(2,true),true);r.Quantity(2);Need(r.Snapshot().view.goals.Single().requests.Single().confirmations.Length==2,"correction chain lost");});
   await test("V04 missing refusal exception preserve data",async()=>{foreach(var mode in new[]{"missing","refuse","exception"}){var r=new Rig();await r.Start(root);if(mode!="missing")Bind(r.c,x=>{if(mode=="exception")throw new IOException("synthetic prompt");return Task.FromResult(false);});await Blocked(r,r.Payload(0));}});
   await test("V05 approval drift rejected",async()=>{foreach(var drift in new[]{"account","character","epoch","revision","quantity","request","target"}){var r=new Rig();await r.Start(root);var p=r.Payload(0);string old=ProgressDomain.Canonical(r.Snapshot().view);Bind(r.c,x=>{if(drift=="account")r.t.actor.SetContext(new Dictionary<string,object>{{"accountId","other"},{"characterId","synthetic-character"},{"accountLabel","other"},{"characterLabel","synthetic"}});if(drift=="character")r.t.actor.SetContext(new Dictionary<string,object>{{"accountId","synthetic-account"},{"characterId","other"},{"accountLabel","synthetic"},{"characterLabel","other"}});if(drift=="epoch")r.t.epoch++;if(drift=="quantity")p["quantity"]=5;if(drift=="request")p["requestId"]=Guid.NewGuid().ToString("D");if(drift=="target")p["goalId"]=Guid.NewGuid().ToString("D");if(drift=="revision"){var s=r.Snapshot();Need(r.t.store.Commit(new ProgressMutation{kind="SetLifecycle",scope=ProgressHostFixture.Scope(),goalId=s.view.goals.Single().goalId,lifecycle="paused"},s.revision,Guid.NewGuid()).status=="committed","peer revision write");}return Task.FromResult(true);});bool blocked=false;try{await r.Send(p);}catch{blocked=true;}Need(blocked&&r.Snapshot().view.goals.Single().requests.Single().quantity==null,"approval drift accepted: "+drift);}});
   await test("V06 monotonic expiry resists wall clock changes",async()=>{foreach(var drift in new[]{"elapsed","elapsed-wall-back","ticks-back","wall-back","wall-forward"}){var r=new Rig();await r.Start(root,false,true);Bind(r.c,x=>{if(drift.StartsWith("elapsed",StringComparison.Ordinal))r.ticks+=120001;if(drift=="ticks-back")r.ticks--;if(drift=="wall-back"||drift=="elapsed-wall-back")r.t.now=r.t.now.AddSeconds(-1);if(drift=="wall-forward")r.t.now=r.t.now.AddSeconds(121);return Task.FromResult(true);});await Blocked(r,r.Payload(0));}});
   await test("V07 writer free but game lease Busy held",async()=>{var r=new Rig();await r.Start(root);Bind(r.c,async x=>{await Task.Yield();using(r.t.store.AcquireWriter(new ProgressLockOwner())){}Need(r.t.actor.Busy,"approval Busy=false");bool held=false;try{using(r.t.journal.AcquireExecutionLease()){};}catch(IOException){held=true;}Need(held,"approval released game lease");return true;});await r.Send(r.Payload(0));r.Quantity(0);});
   await test("V08 unknown never approved",async()=>{var r=new Rig();await r.Start(root,true);var before=File.ReadAllBytes(r.t.journal.FilePath);int prompts=0;Bind(r.c,x=>{prompts++;return Task.FromResult(true);});await Blocked(r,r.Payload(0));Need(prompts==0&&before.SequenceEqual(File.ReadAllBytes(r.t.journal.FilePath)),"unknown changed");});
   await test("V09 lost ACK latest view no duplicate prompt",async()=>{var r=new Rig();await r.Start(root);int prompts=0;Bind(r.c,x=>{prompts++;return Task.FromResult(true);});var p=r.Payload(0);await r.Send(p);await r.Send(r.Payload(2,true),true);long revision=r.Snapshot().revision;var ack=(ProgressCommitResult)await r.Send(p);Need(ack.status=="already-applied"&&ack.view.goals.Single().confirmedQuantity==2&&r.Snapshot().revision==revision&&prompts==2,"old ACK rolled back or re-prompted");p["quantity"]=1;await Blocked(r,p);});
   await test("V10 storage failure preserves native terminal",async()=>{var r=new Rig();await r.Start(root);var native=File.ReadAllBytes(r.t.journal.FilePath);Bind(r.c,x=>{r.disk.fail=true;return Task.FromResult(true);});await Blocked(r,r.Payload(0));Need(native.SequenceEqual(File.ReadAllBytes(r.t.journal.FilePath))&&r.t.calls==1,"write failure rewrote native or replayed");});
   await test("V11 correction target and reason cannot change during approval",async()=>{foreach(var drift in new[]{"target","reason"}){var r=new Rig();await r.Start(root);await r.Send(r.Payload(3));var p=r.Payload(2,true);Bind(r.c,x=>{if(drift=="target")p["supersedesEventId"]=Guid.NewGuid().ToString("D");else p["reason"]="changed reason";return Task.FromResult(true);});await Blocked(r,p,true);r.Quantity(3);}});
   await test("V12 final inspection drift cannot bypass commit checks",async()=>{foreach(var drift in new[]{"character","epoch","elapsed","quantity"}){var r=new Rig();await r.Start(root,false,true);var p=r.Payload(0);Bind(r.c,x=>{r.disk.afterRead=()=>{if(drift=="character")r.t.actor.SetContext(new Dictionary<string,object>{{"accountId","synthetic-account"},{"characterId","other"},{"accountLabel","synthetic"},{"characterLabel","other"}});if(drift=="epoch")r.t.epoch++;if(drift=="elapsed")r.ticks+=120001;if(drift=="quantity")p["quantity"]=5;};return Task.FromResult(true);});await Blocked(r,p);Need(r.t.calls==1,"inspection drift replayed command");}});
await test("V13 every positive and duplicate commit rechecks final IO context",async()=>{foreach(var duplicate in new[]{false,true})foreach(var readIndex in duplicate?new[]{1,2}:new[]{1,2,3})foreach(var drift in new[]{"account","character","aba","epoch","quantity"}){var r=new Rig();await r.Start(root);var p=r.Payload(3);if(duplicate)await r.Send(p);int reads=readIndex;Action driftRead=null;driftRead=()=>{if(--reads>0){r.disk.afterRead=driftRead;return;}var original=r.t.actor.ProgressContext();if(drift=="epoch")r.t.epoch++;else if(drift=="quantity")p["quantity"]=2;else{r.t.actor.SetContext(new Dictionary<string,object>{{"accountId",drift=="account"?"other":"synthetic-account"},{"characterId","other"},{"accountLabel","synthetic"},{"characterLabel","other"}});if(drift=="aba")r.t.actor.SetContext(new Dictionary<string,object>{{"accountId",original["accountId"]},{"characterId",original["characterId"]},{"accountLabel",original["accountLabel"]},{"characterLabel",original["characterLabel"]}});}};r.disk.afterRead=driftRead;await Blocked(r,p);Need(r.t.calls==1,"context drift replayed game");}});
   await test("V14 post-publish context change rejects ACK but preserves one committed result",async()=>{var r=new Rig();await r.Start(root);var p=r.Payload(3);int reads=4;Action drift=null;drift=()=>{if(--reads>0){r.disk.afterRead=drift;return;}r.t.epoch++;};r.disk.afterRead=drift;bool rejected=false;try{await r.Send(p);}catch{rejected=true;}Need(rejected,"stale post-publish ACK accepted");r.Quantity(3);var ack=(ProgressCommitResult)await r.Send(p);Need(ack.status=="already-applied"&&r.Snapshot().view.goals.Single().requests.Single().confirmations.Length==1&&r.t.calls==1,"post-publish result lost or duplicated");});
   await test("V15 lifecycle commit rejects epoch drift inside storage",async()=>{var r=new Rig();await r.Start(root);var view=r.Snapshot();var p=new Dictionary<string,object>{{"accountId","synthetic-account"},{"characterId","synthetic-character"},{"revision",view.revision},{"operationId",Guid.NewGuid().ToString("D")},{"goalId",view.view.goals.Single().goalId},{"lifecycle","paused"}};int reads=2;Action drift=null;drift=()=>{if(--reads>0){r.disk.afterRead=drift;return;}r.t.epoch++;};var before=File.ReadAllBytes(r.t.store.FilePath);r.disk.afterRead=drift;bool rejected=false;try{await ProgressHostFixture.Request(r.c,"setLifecycle",p);}catch{rejected=true;}Need(rejected&&before.SequenceEqual(File.ReadAllBytes(r.t.store.FilePath)),"stale lifecycle published");});
   if(failed>0)throw new Exception("quantity failures: "+failed);
  }
 }
}
